#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: land AWS SSO on op-usxpress-prod. INFRA-1661.
#
# Written 2026-10-26. Runs on WSL, not in a codespace: it needs talosctl, the
# AWS SSO profiles, the on-prem kubeconfigs and the Octopus CLI config.
#
# What makes this procedure dangerous, and the whole reason it is a wizard:
# the apiserver flag names a HOST path, and kube-apiserver does not start if
# that file is absent. Stage 1 proves the file. Stage 2 opens the escape hatch
# BEFORE anything changes. Neither is skippable.
#
# Three traps this encodes, each already paid for on QA:
#   * TfApply is TRUE for production and false everywhere else, so a prod
#     deploy applies for real. Nobody deploys prod "to see the plan".
#   * Octopus reads TF_VAR_* as env.auto.tfvars. A value in
#     deploy/terraform/envs/prod.tfvars is never read and the deploy goes green.
#   * A release pins a variable SNAPSHOT. Adding the variable does not reach an
#     existing release, so stage 5 is not optional bookkeeping.
#
# NOT in here, deliberately: the Flux-rules copy (INFRA-1657) and alert
# delivery (INFRA-1659). Different repo, different risk, no reason to couple
# them to a control-plane change. Stage 8 names them so they are not lost.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

REPO="${REPO:-$HOME/eks_code}"
PROD_ACCOUNT=937464026810
PROD_ENDPOINT=10.10.82.52
HOSTFILE=/var/lib/aws-iam-authenticator/kubeconfig.yaml
OCTO=https://octopus.usxpress.io
BREAKGLASS="$HOME/.kube/op-usxpress-prod-breakglass.yaml"

# prod_kubeconfig prints the single-cluster kubeconfig whose server is prod's,
# or nothing. Never match on a filename: op-usxpress-dev.yaml on this box has
# pointed at a CLOUD EKS cluster before.
prod_kubeconfig() {
  local f s
  for f in "$HOME"/.kube/*.yaml "$HOME"/.kube/*.yml; do
    [[ -f "$f" ]] || continue
    s=$(kubectl --kubeconfig="$f" config view \
        -o jsonpath='{.clusters[*].cluster.server}' 2>/dev/null || true)
    [[ $(echo "$s" | wc -w) -eq 1 ]] || continue
    [[ "$s" == *"$PROD_ENDPOINT:6443"* ]] && { printf '%s' "$f"; return 0; }
  done
  return 1
}

banner "AWS SSO on op-usxpress-prod  (INFRA-1661)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prove the webhook file exists on every control-plane node"
say "kube-apiserver will not start if $HOSTFILE"
say "is missing. The DaemonSet writes it, so '3/3 ready' is the writer being"
say "healthy -- not the file being there."
say ""
say "QA runs first and is a CONTROL, not a convenience: QA already carries the"
say "flag with a healthy API server, so QA MUST show the file. If it does not,"
say "the method is wrong and prod's answer means nothing."
pause "Press Enter to run the check (read-only)"
if bash "$REPO/scripts/check-authenticator-webhook-file.sh" qa \
   && bash "$REPO/scripts/check-authenticator-webhook-file.sh" prod; then
  say ""
  say "${GREEN}Both PASS.${RESET} The prerequisite is met."
else
  say ""
  say "${RED}Not both PASS.${RESET} Read which it was:"
  step "QA failed       -> the method is wrong. Fix the check, not the cluster."
  step "no live session -> it names the profile. Log in and re-run."
  step "may not read    -> the platform-admin gap. Run STAGE 3 FIRST:"
  say "                     bash $REPO/scripts/idc-grant-secretsmanager.sh op-prod"
  say "                   then ALLOW_PROD_WRITE=yes ... --apply, then re-run this."
  step "prod ABSENT     -> a real finding. The flag would break the API server."
  say ""
  say "Only the last of those is about the cluster. The rest are about us."
  say ""
  say "Stopping. None of the remaining stages are safe without this."
  exit 1
fi
confirm "Continue to the escape hatch?" || { say "Stopped."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Open break-glass, and keep it open"
say "The safety property that makes stage 6 survivable: the flag needs the"
say "FILE, not a running authenticator. If webhook auth fails, x509 still"
say "works -- so the certificate kubeconfig stays a way in."
say ""
say "That escape hatch only exists if someone is already holding it."
say ""
say "Your local ~/.talos/config does NOT carry prod's CA. The authoritative"
say "talosconfig is in Secrets Manager, which is what this script fetches."
pause "Press Enter to build the break-glass kubeconfig"
bash "$REPO/scripts/breakglass-prod-kubeconfig.sh"
say ""
if kubectl --kubeconfig="$BREAKGLASS" get --raw /version >/dev/null 2>&1; then
  say "${GREEN}Break-glass answers.${RESET}  $BREAKGLASS"
else
  say "${RED}Break-glass does NOT answer.${RESET} Do not proceed: there is no way back in."
  exit 1
fi
say ""
say "${BOLD}Now open a SECOND terminal and leave this running in it:${RESET}"
say "  watch -n5 kubectl --kubeconfig=$BREAKGLASS get nodes"
say ""
say "Do not close it until stage 7 passes."
confirm "Is the second terminal open and showing nodes?" \
  || { say "Open it first, then re-run. Stopped."; exit 0; }

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Let the prod platform admin write its own secrets"
say "op-prod-platform-admin holds only sts:GetCallerIdentity, so the person who"
say "owns the platform cannot read or rotate any secret the platform depends on."
say "QA was fixed 2026-08-25; prod never was. Independent of the control plane,"
say "so it lands before the risky step."
say ""
say "And it may GATE stage 1: reading prod's talosconfig out of Secrets Manager"
say "needs this grant, unless another prod profile already has broader rights."
say "If stage 1 said 'none of them may read', this stage is the unblock."
say ""
say "The trap this guards: put-inline-policy-to-permission-set REPLACES the whole"
say "inline policy. The script reads the current one and merges."
pause "Press Enter for the DRY RUN (writes nothing)"
DRY_OK=yes
bash "$REPO/scripts/idc-grant-secretsmanager.sh" op-prod || DRY_OK=no
say ""
if [ "$DRY_OK" = "no" ]; then
  say "${YELLOW}The dry run failed, so there is no merged policy to approve.${RESET}"
  say "Offering an apply here would ask you to confirm something you were never"
  say "shown. Read the error above: 'no permission set named ...' means the"
  say "permission set does not exist, which is a different problem from a"
  say "missing grant and is not fixed by this script."
  say ""
  say "Skipping stage 3. It is independent of the rest, so the cutover can go on."
  pause
elif confirm "Does the merged policy look right, and should I apply it?"; then
  ALLOW_PROD_WRITE=yes bash "$REPO/scripts/idc-grant-secretsmanager.sh" op-prod --apply
  say ""
  say "${GREEN}Applied.${RESET}"
else
  say "Skipped. Nothing was written. This stage can be re-run on its own."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Can Octopus deploy this project at all?"
say "Measured 2026-10-26: the iaac-talos project was DISABLED, so the release"
say "page says 'releases cannot be created' and Create Release is greyed out."
say "Stages 5 and 6 are the two that carry the change, and neither can run on a"
