  say "${GREEN}Deployable.${RESET} Carry on."
else
  say ""
  say "${RED}The Octopus half cannot proceed.${RESET}"
  say ""
  say "If it is DISABLED, that is a decision and not a defect to route around."
  say "TfApply is true for production on this project, so disabling it is a"
  say "plausible deliberate safety catch -- re-enabling makes every future prod"
  say "deploy apply for real, not just this one."
  say ""
  say "Find out who disabled it and why before re-enabling. Everything landed so"
  say "far keeps: the file is proven on all three nodes and break-glass works."
  exit 1
fi
confirm "Continue to the variable?" || { say "Stopped."; exit 0; }

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Add the Octopus variable, scoped to production"
say "Octopus injects TF_VAR_* as env.auto.tfvars and never uses -var-file. So"
say "enable_aws_iam_authenticator = true in deploy/terraform/envs/prod.tfvars"
say "is NOT what a deploy reads -- and the deploy goes green either way."
say ""
say "The variable is the thing that matters:"
say "  TF_VAR_enable_aws_iam_authenticator = true   scope: production"
say ""
say "TfApply is already true for production, so nothing is needed there."
pause "Press Enter for the DRY RUN (writes nothing)"
V="$REPO/wip/onprem-qa-access/aws-sso-webhook/add-octopus-var.py"
python3 "$V" --name TF_VAR_enable_aws_iam_authenticator \
             --value true --env production || true
say ""
say "If it says the variable is already present for production, this stage is"
say "already done -- go on to stage 5."
if confirm "Add the variable now?"; then
  python3 "$V" --name TF_VAR_enable_aws_iam_authenticator \
               --value true --env production --apply
  say ""
  say "${GREEN}Variable added.${RESET}"
else
  say "Skipped."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Re-snapshot the release (this is not bookkeeping)"
say "A release pins the variable snapshot taken when it was CREATED. The"
say "variable you just added does not reach an existing release, and deploying"
say "without this is another silent no-op that reports Success."
say ""
step "Open the iaac-talos project in Octopus."
step "Either click 'Update Variables' on the release you intend to deploy,"
step "or cut a NEW release. Both work; a new release is easier to audit."
open_url "$OCTO/app#/Spaces-2/projects/iaac-talos/deployments/releases"
say ""
ask REL "Which release will you deploy? (e.g. 1.4.7)"
say ""
say "Release recorded: $REL"
confirm "Have you clicked Update Variables, or cut a new release?" \
  || { say "Do that first. Stopped before the deploy."; exit 0; }

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy to Production, and watch the control plane roll"
say "${RED}${BOLD}This is the step that can take prod down.${RESET}"
say ""
say "TfApply is TRUE for production. This deploy APPLIES. It is not a plan."
say ""
say "Three control-plane nodes restart kube-apiserver one at a time. Two stay"
say "up while one rolls, so a bad flag costs one node and not the cluster --"
say "as long as you are watching and stop after the first."
say ""
step "Deploy release $REL to Production in Octopus."
step "Watch the second terminal. All nodes must stay Ready."
