open_url "$OCTO/app#/Spaces-2/projects/iaac-talos/deployments/releases"
say ""
pause "Press Enter once the Octopus deploy has finished"
K=$(prod_kubeconfig || true)
if [[ -z "$K" ]]; then
  say "${YELLOW}No prod kubeconfig found; using break-glass to read state.${RESET}"
  K="$BREAKGLASS"
fi
say ""
say "-- control-plane nodes"
kubectl --kubeconfig="$K" get nodes -l node-role.kubernetes.io/control-plane || true
say ""
say "-- is the flag on the API server now?"
kubectl --kubeconfig="$K" -n kube-system get pods -o name 2>/dev/null \
  | grep -i kube-apiserver | head -1 \
  | xargs -r -I{} kubectl --kubeconfig="$K" -n kube-system get {} \
      -o jsonpath='{.spec.containers[0].command}{.spec.containers[0].args}' 2>/dev/null \
  | tr ',' '\n' | grep -i 'authentication-token-webhook' \
  || say "  ${YELLOW}flag still ABSENT -- the deploy did not carry the variable.${RESET}"
say ""
say "A still-absent flag after a Success almost always means the release was"
say "not re-snapshotted. Go back to stage 5; do not re-deploy blindly."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Prove a human can log in with SSO"
say "The flag being present is the mechanism. This is the property."
say ""
say "On QA this returned sso:doke@usxpress.com with the group"
say "onprem-platform-admins, and no certificate involved. Prod's admin ARN in"
